#!/usr/bin/env node
/**
 * The routine dependency refresh, run by promote.yml after a production promotion (Dependabot opens
 * security updates only: .github/dependabot.yml). It opens ONE pull request,
 * "chore(deps): refresh dependencies after promotion <label>", holding:
 *
 *   1. npm: `pnpm update --recursive` -- the newest versions inside each package.json range, never a new
 *      major (no --latest); the lockfile is regenerated by it. A specifier whose major moved anyway stops
 *      the refresh;
 *   2. GitHub Actions: every `uses: owner/repo@vX.Y[.Z]` in .github/workflows, .github/actions and
 *      visual-review/templates moves to the newest tag of the same major (a major tag such as `@v4`
 *      already floats, and a commit pin is left alone); then visual-seed.yml, which `visual-review init`
 *      generates from its template, is regenerated, never edited.
 *
 * Nothing to update opens nothing. The two parts are separate commits: a token without the Workflows
 * permission cannot push a change under .github/workflows/, and then the npm commit is pushed alone.
 *
 * Usage: node tools/dependency-refresh.mjs [--dry-run] [--label <version or date>]
 *   --dry-run  makes the updates in the checkout and lists the changed files; no branch, commit, push or
 *              pull request
 * Needs GH_TOKEN (graphty-agent's, Contents and Pull requests write) unless --dry-run.
 */
import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const USES = /(uses:\s*["']?)([\w.-]+\/[\w.-]+)((?:\/[\w./-]+)?)@v(\d+)((?:\.\d+){1,2})\b/g;
const GENERATED = ".github/workflows/visual-seed.yml";
const DEP_FIELDS = ["dependencies", "devDependencies", "optionalDependencies", "peerDependencies"];

const defaultRun = (cmd, args, opts = {}) =>
    execFileSync(cmd, args, { encoding: "utf8", maxBuffer: 1 << 28, stdio: ["ignore", "pipe", "inherit"], ...opts });

/**
 * The `vX.Y.Z` tags of a GitHub repository.
 * @param repo owner/name
 * @param run the command runner
 * @returns the tag names
 */
export function remoteTags(repo, run = defaultRun) {
    const out = run("git", ["ls-remote", "--tags", "--refs", `https://github.com/${repo}`]);
    return [...out.matchAll(/refs\/tags\/(v\d+(?:\.\d+){1,2})$/gm)].map((m) => m[1]);
}

const parts = (tag) => tag.slice(1).split(".").map(Number);
const newer = (a, b) => {
    for (let i = 0; i < 3; i++) if ((a[i] ?? 0) !== (b[i] ?? 0)) return (a[i] ?? 0) > (b[i] ?? 0);
    return false;
};

/**
 * `text` with every minor/patch-pinned action moved to the newest tag of its major.
 * @param text a workflow or template
 * @param tagsOf the tags of a repository
 * @returns the text with the bumped refs
 */
export function bumpActionRefs(text, tagsOf) {
    return text.replaceAll(USES, (all, pre, repo, sub, major, rest) => {
        const current = parts(`v${major}${rest}`);
        let best = null;
        for (const tag of tagsOf(repo)) {
            const p = parts(tag);
            if (p[0] === current[0] && p.length === current.length && newer(p, best ?? current)) best = p;
        }
        return best ? `${pre}${repo}${sub}@v${best.join(".")}` : all;
    });
}

const listYaml = (dir) => {
    try {
        return readdirSync(dir, { recursive: true })
            .filter((f) => /\.ya?ml$/.test(f))
            .map((f) => join(dir, f));
    } catch {
        return [];
    }
};

/**
 * Each package.json's dependency specifiers, by file and name.
 * @param cwd the checkout
 * @param run the command runner
 * @returns specifiers keyed by "<file> <name>"
 */
function specifiers(cwd, run) {
    const files = run("git", ["ls-files", "package.json", "*/package.json"], { cwd }).split("\n").filter(Boolean);
    const all = {};
    for (const f of files) {
        const pkg = JSON.parse(readFileSync(join(cwd, f), "utf8"));
        for (const field of DEP_FIELDS) for (const [n, s] of Object.entries(pkg[field] ?? {})) all[`${f} ${n}`] = s;
    }
    return all;
}
const majorOf = (spec) => /^[\^~>=<\s]*v?(\d+)/.exec(spec)?.[1];

const changedFiles = (cwd, run) =>
    run("git", ["status", "--porcelain", "--untracked-files=all"], { cwd })
        .split("\n")
        .filter(Boolean)
        .map((l) => l.slice(3));

/**
 * Makes the updates in `cwd` and returns `{ npm, actions }`, the files each part changed.
 * @param o options
 * @param o.cwd the checkout
 * @param o.run the command runner
 * @param o.tagsOf the tags of a repository (default: git ls-remote)
 * @returns the changed files of each part
 */
export function update({ cwd, run = defaultRun, tagsOf }) {
    tagsOf ??= (() => {
        const cache = new Map();
        return (repo) => cache.get(repo) ?? cache.set(repo, remoteTags(repo, run)).get(repo);
    })();
    const before = specifiers(cwd, run);
    run("pnpm", ["update", "--recursive"], { cwd, stdio: "inherit" });
    const after = specifiers(cwd, run);
    const crossed = Object.keys(after).filter((k) => before[k] && majorOf(before[k]) !== majorOf(after[k]));
    if (crossed.length) throw new Error(`a major moved, which a refresh never does: ${crossed.join(", ")}`);
    const npm = changedFiles(cwd, run);

    const files = [
        ...listYaml(join(cwd, ".github/workflows")),
        ...listYaml(join(cwd, ".github/actions")),
        ...listYaml(join(cwd, "visual-review/templates")),
    ].filter((f) => !f.endsWith(GENERATED));
    for (const f of files) {
        const text = readFileSync(f, "utf8");
        const bumped = bumpActionRefs(text, tagsOf);
        if (bumped !== text) writeFileSync(f, bumped);
    }
    // Regenerated from the template every time, never hand-edited (CLAUDE.md, "Visual review").
    rmSync(join(cwd, GENERATED), { force: true });
    run("pnpm", ["exec", "visual-review", "init"], { cwd, stdio: "inherit" });
    const actions = changedFiles(cwd, run).filter((f) => !npm.includes(f));
    return { npm, actions };
}

/**
 * Commits, pushes and opens the pull request. Returns its URL, or null when nothing changed.
 * @param o options
 * @param o.cwd the checkout
 * @param o.label the promoted version or the date
 * @param o.npm the files the npm part changed
 * @param o.actions the files the Actions part changed
 * @param o.run the command runner
 * @returns the pull request's URL, or null
 */
export function openPullRequest({ cwd, label, npm, actions, run = defaultRun }) {
    if (!npm.length && !actions.length) return null;
    const branch = `chore/deps-refresh-${label.replaceAll(/[^\w.-]+/g, "-")}`;
    const title = `chore(deps): refresh dependencies after promotion ${label}`;
    const git = (...args) => run("git", args, { cwd });
    git("switch", "-c", branch);
    if (npm.length) {
        git("add", "--", ...npm);
        git("commit", "-m", `${title}\n\nnpm: pnpm update --recursive, within every package.json range.`);
    }
    if (actions.length) {
        git("add", "--", ...actions);
        git("commit", "-m", `chore(deps): GitHub Actions minor and patch bumps after promotion ${label}`);
    }
    let note = "";
    try {
        git("push", "--no-verify", "origin", `HEAD:refs/heads/${branch}`);
    } catch (e) {
        if (!actions.length || !npm.length) throw e;
        git("push", "--no-verify", "origin", `HEAD~1:refs/heads/${branch}`);
        note = `\nThe GitHub Actions bumps were not pushed (${actions.join(", ")}): the token may not change workflows.\n`;
    }
    const body = [
        "Routine dependency refresh after a production promotion (.github/dependabot.yml opens security updates only).",
        "",
        "No issue",
        note,
        "## Proof",
        "",
        "`node tools/dependency-refresh.mjs` in promote.yml: `pnpm update --recursive` (no `--latest`, so no new",
        "major), GitHub Actions moved within their major, `visual-review init` regenerated visual-seed.yml.",
        "",
        `Changed: ${[...npm, ...actions].join(", ")}`,
        "",
        "CI on this pull request is the test. An agent adds the fresh review (`tools/pr-open.sh` on this branch).",
    ].join("\n");
    const url = run("gh", ["pr", "create", "--base", "master", "--head", branch, "--title", title, "--body", body], {
        cwd,
    }).trim();
    run("gh", ["pr", "merge", "--auto", "--merge", url], { cwd });
    return url;
}

function main(argv) {
    const dryRun = argv.includes("--dry-run");
    const i = argv.indexOf("--label");
    const label = i >= 0 ? argv[i + 1] : new Date().toISOString().slice(0, 10);
    const cwd = process.cwd();
    const { npm, actions } = update({ cwd });
    if (!npm.length && !actions.length) {
        console.log("dependency refresh: nothing to update; no pull request");
        return;
    }
    console.log(`dependency refresh: npm ${npm.join(", ") || "-"}; actions ${actions.join(", ") || "-"}`);
    if (dryRun) return;
    console.log(openPullRequest({ cwd, label, npm, actions }));
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main(process.argv.slice(2));
